import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CzfUxB_Q.js";const p=JSON.parse('{"title":"2026年学习日志","description":"","frontmatter":{},"headers":[],"relativePath":"src/other/2026年的碎碎念.md","filePath":"src/other/2026年的碎碎念.md","lastUpdated":1777778134000}'),o={name:"src/other/2026年的碎碎念.md"};function h(l,a,n,s,d,_){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_2026年学习日志" tabindex="-1">2026年学习日志 <a class="header-anchor" href="#_2026年学习日志" aria-label="Permalink to &quot;2026年学习日志&quot;">​</a></h1><p>偶尔记录心情，记录生活，记录工作，记录学习，记录生活中的感触，记录生活中的喜怒哀乐。不知道记录啥随便写的.....</p><h2 id="_2026-5-3" tabindex="-1">2026.5.3 <a class="header-anchor" href="#_2026-5-3" aria-label="Permalink to &quot;2026.5.3&quot;">​</a></h2><p>迅速过完一遍react19, nextjs也差不多学完了, 感觉很多东西都没学会没记住, 接下来就是继续重复学习, 直至熟练.</p><h2 id="_2026-4-28" tabindex="-1">2026.4.28 <a class="header-anchor" href="#_2026-4-28" aria-label="Permalink to &quot;2026.4.28&quot;">​</a></h2><p>vue3学完了, 还顺带做了两个小项目, 一个大项目.准备开始学习React, 然后就是nextjs.</p><p>更改了一下知识库的目录结构, 又学到了新的东西</p><h2 id="_2026-4-11" tabindex="-1">2026.4.11 <a class="header-anchor" href="#_2026-4-11" aria-label="Permalink to &quot;2026.4.11&quot;">​</a></h2><p>忙了一两个小时去调试爬虫，结果啥都能爬下来，偏偏我想要的东西爬不下来.....心态小崩!</p><h2 id="_2026-4-1" tabindex="-1">2026.4.1 <a class="header-anchor" href="#_2026-4-1" aria-label="Permalink to &quot;2026.4.1&quot;">​</a></h2><p>今天是愚人节，现在是早上06:43.最近作息调整到晚上九点睡觉，早上五点半醒来，一时不知道是好是坏，感觉作息还是蛮健康的....</p><h2 id="_2026-3-25" tabindex="-1">2026.3.25 <a class="header-anchor" href="#_2026-3-25" aria-label="Permalink to &quot;2026.3.25&quot;">​</a></h2><p>考研成绩2.28号出的，没考上....最近学完了vue3，并且练习了半个项目，有些方面还是不熟练。现在准备练习Tailwindcss，并尝试用Tailwindcss来改写一个项目。最近还在学封装Axios，学习RBAC权限管理。</p><h2 id="_2026-2-25" tabindex="-1">2026.2.25 <a class="header-anchor" href="#_2026-2-25" aria-label="Permalink to &quot;2026.2.25&quot;">​</a></h2><p>本来是说24号出考研初试成绩的，结果兜兜转转没出，没有人知道为什么，也没有人知道今年的成绩什么时候出。。。</p><h2 id="_2026-2-2" tabindex="-1">2026.2.2 <a class="header-anchor" href="#_2026-2-2" aria-label="Permalink to &quot;2026.2.2&quot;">​</a></h2><p>ajax、JavaScript和vite学完，最近效率还不错....</p><h2 id="_2026-1-27" tabindex="-1">2026.1.27 <a class="header-anchor" href="#_2026-1-27" aria-label="Permalink to &quot;2026.1.27&quot;">​</a></h2><p>学完了前端三件套基础知识，感觉学习时间有点太长了，最近学习效率不怎么高！下面开始学习Ajax和tailwindcss,之后是vite。</p><h2 id="_2026-1-15" tabindex="-1">2026.1.15 <a class="header-anchor" href="#_2026-1-15" aria-label="Permalink to &quot;2026.1.15&quot;">​</a></h2><p>加入L站！解锁新天地！</p><h2 id="_2026-1-4" tabindex="-1">2026.1.4 <a class="header-anchor" href="#_2026-1-4" aria-label="Permalink to &quot;2026.1.4&quot;">​</a></h2><p>大晚上的连不上github，代码推不上去.....感觉一干正事，机场就不太好用了。之前不学习的时候，也没觉得这个机场有什么不好用的。现在一天推三四次代码，感觉就一次能推上去。要是之后再影响体验就换一个好点的。</p>',23)])])}const u=e(o,[["render",h]]);export{p as __pageData,u as default};
